import 'dart:io';
import 'package:flutter_test/flutter_test.dart';
import 'package:seguimiento/ui/exercise_figure_3d.dart' as current;
import 'package:seguimiento/ui/exercise_figure_3d_view.dart' as view;
import 'exercise_figure_3d_pre_exact.dart' as previous;

void main() {
  test('pre-fix clamp fails both geometric limit and real playback continuity', () {
    final source = File(current.Figure3DCatalog.asset).readAsStringSync();
    final timeline = current.Figure3DCatalog.fromJsonString(source).forExercise('Burpees')!;
    final old = previous.Figure3DCatalog.fromJsonString(source).forExercise('Burpees')!;
    final time = timeline.motion.take(4).fold<double>(0, (sum, stage) => sum + stage.seconds);
    double delta(double a, double b) {
      final before = previous.liftSkeleton(old.skeletonAt(a), old).p['nearKnee']!;
      final after = previous.liftSkeleton(old.skeletonAt(b), old).p['nearKnee']!;
      return (after - before).length;
    }
    final geometric = delta((4 - 1e-10) / old.motion.length, (4 + 1e-10) / old.motion.length);
    final playback = delta(view.figureMotionProgress(timeline, time - 1e-4),
        view.figureMotionProgress(timeline, time + 1e-4));
    expect([geometric, playback], everyElement(lessThan(.01)));
  });
}
